3	/**
4	 * el.outerHTML is not polyfilled so we need to recreate the tag + attributes and
5	 * combine it with el.innerHTML.
6	 *
7	 * @param {Element} el Element you want to get the out Html from
8	 * @returns {String} outer html
9	 */
10	export const getOuterHtml = el => {
11	  /* istanbul ignore next */
12	  if (window.ShadyCSS && window.ShadyCSS.nativeShadow === false) {
13	    const tagName = el.tagName.toLowerCase();
14	    let attributes = ' ';
15	    Array.prototype.slice.call(el.attributes).forEach(item => {
16	      attributes += `${item.name}="${item.value}" `;
17	    });
18	    // removes last ' ' or if there are no attributes makes it to equal ''
19	    attributes = attributes.slice(0, -1);
20	    return `<${tagName}${attributes}>${el.innerHTML}</${tagName}>`;
21	  }
22	  return el.outerHTML;
23	};
